CREATE TABLE ingestion_connectors(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL,connector_type VARCHAR(40) NOT NULL,configuration_json TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE ingestion_runs(id UUID PRIMARY KEY,connector_id UUID NOT NULL REFERENCES ingestion_connectors(id),dataset_id UUID REFERENCES datasets(id),status VARCHAR(24) NOT NULL,started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,records_read BIGINT NOT NULL DEFAULT 0,records_written BIGINT NOT NULL DEFAULT 0,error_message TEXT);
CREATE TABLE experiments(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,dataset_id UUID REFERENCES datasets(id),parameters_json TEXT NOT NULL,metrics_json TEXT NOT NULL DEFAULT '{}',status VARCHAR(24) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_experiments_created ON experiments(created_at DESC);
CREATE TABLE registered_models(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,description TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE model_versions(id UUID PRIMARY KEY,model_id UUID NOT NULL REFERENCES registered_models(id) ON DELETE CASCADE,version INTEGER NOT NULL,experiment_id UUID REFERENCES experiments(id),artifact_uri TEXT NOT NULL,framework VARCHAR(80) NOT NULL,parameters_json TEXT NOT NULL,metrics_json TEXT NOT NULL,stage VARCHAR(24) NOT NULL DEFAULT 'NONE',created_at TIMESTAMPTZ NOT NULL,UNIQUE(model_id,version));
CREATE TABLE feature_sets(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,description TEXT,dataset_id UUID REFERENCES datasets(id),entity_key VARCHAR(160) NOT NULL,feature_schema_json TEXT NOT NULL,transformation_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE scheduled_jobs(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL,pipeline_id UUID REFERENCES pipelines(id),cron_expression VARCHAR(120) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,next_run_at TIMESTAMPTZ,last_run_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_scheduled_jobs_due ON scheduled_jobs(enabled,next_run_at);
CREATE TABLE sbase_roles(id UUID PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description TEXT);
CREATE TABLE sbase_role_permissions(role_id UUID NOT NULL REFERENCES sbase_roles(id) ON DELETE CASCADE,permission VARCHAR(120) NOT NULL,PRIMARY KEY(role_id,permission));
CREATE TABLE sbase_user_roles(subject VARCHAR(200) NOT NULL,role_id UUID NOT NULL REFERENCES sbase_roles(id) ON DELETE CASCADE,PRIMARY KEY(subject,role_id));
CREATE TABLE dashboards(id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,layout_json TEXT NOT NULL DEFAULT '{}',owner_subject VARCHAR(200) NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE dashboard_widgets(id UUID PRIMARY KEY,dashboard_id UUID NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,title VARCHAR(160) NOT NULL,widget_type VARCHAR(40) NOT NULL,query_json TEXT NOT NULL,position_x INTEGER NOT NULL DEFAULT 0,position_y INTEGER NOT NULL DEFAULT 0,width INTEGER NOT NULL DEFAULT 6,height INTEGER NOT NULL DEFAULT 4);